const tickets = $('Skip reviewed tickets').all();
const allowedCategories = ['billing', 'technical', 'account_access', 'feature_request', 'other'];
const allowedUrgencies = ['high', 'medium', 'low'];

return $input.all().map((item, i) => {
  const ticket = tickets[i].json;
  const text = (item.json.content || [])
    .filter((block) => block.type === 'text')
    .map((block) => block.text)
    .join('\n')
    .replace(/```json|```/g, '')
    .trim();

  let result = {};
  let problem = item.json.error ? 'AI call failed after retries' : '';

  if (!problem) {
    try {
      result = JSON.parse(text);
    } catch (error) {
      problem = 'AI result is not valid JSON';
    }
  }

  if (!problem && !allowedCategories.includes(result.category)) {
    problem = `Category not allowed: ${result.category}`;
  }
  if (!problem && !allowedUrgencies.includes(result.urgency)) {
    problem = `Urgency not allowed: ${result.urgency}`;
  }
  if (!problem && (typeof result.reason !== 'string' || !result.reason.trim())) {
    problem = 'Reason is missing';
  }

  return {
    json: {
      ticket_id: ticket.ticket_id,
      customer_name: ticket.customer_name,
      subject: ticket.subject,
      message: ticket.message,
      category: problem ? 'needs_manual_check' : result.category,
      urgency: problem ? 'needs_manual_check' : result.urgency,
      reason: problem || result.reason.trim(),
      triage_ok: !problem,
    },
  };
});

const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const L = '\\p{L}\\p{N}';
const endings = '(?:a|o|u|owi|em|ie|ę|ą|y|i|e|ego|emu|ym|ej|iej|om|owie|owej|ową|owa)?';

const firstNames = ['Adam','Adrian','Agata','Agnieszka','Aleksandra','Alicja','Ana','Andrzej','Anna','Antonio','Barbara','Bartosz','Beata','Carlos','Carmen','Daniel','Daniela','Dawid','Diego','Dominik','Dorota','Edyta','Elena','Elżbieta','Emilia','Ewa','Fernando','Filip','Francisco','Gabriel','Gabriela','Grzegorz','Hanna','Iwona','Jakub','Jan','Javier','Joanna','John','Jorge','José','Juan','Julia','Justyna','Kamil','Karolina','Katarzyna','Klaudia','Krzysztof','Lucía','Lucia','Luis','Łukasz','Maciej','Magdalena','Małgorzata','Manuel','Marcin','Marek','María','Maria','Mariusz','Marta','Mateusz','Michał','Miguel','Monika','Natalia','Oliwia','Olivia','Pablo','Patryk','Paweł','Pedro','Piotr','Rafał','Robert','Sandra','Sara','Sebastian','Sofía','Sylwia','Szymon','Tomasz','Wojciech','Zofia','Żaneta'];

// Reduce a name to a stem, so that Marek also matches Marka and Anna matches Anny.
const stemOf = (name) => {
  if (name.length < 4) return name;
  const lower = name.toLowerCase();
  if (lower.endsWith('ek')) return name.slice(0, -2);
  if (lower.endsWith('ski') || lower.endsWith('cki')) return name.slice(0, -1);
  if (lower.endsWith('ska') || lower.endsWith('cka')) return name.slice(0, -1);
  if (/[aeiouyąęó]$/i.test(name)) return name.slice(0, -1);
  return name;
};

const nameRegex = (stem, flags) => new RegExp(
  `(?<![${L}])${escapeRegex(stem)}(?:${endings}|k${endings}|iego|iemu|im|ą)(?![${L}])`,
  flags
);

const maskPatterns = (text) => String(text || '')
  .replace(/[\p{L}0-9._%+-]+@[\p{L}0-9.-]+\.\p{L}{2,}/gu, '[EMAIL]')
  .replace(/\b[A-Z]{2}\d{2}(?:[ -]?[A-Z0-9]{4}){2,7}(?:[ -]?[A-Z0-9]{1,3})?\b/g, '[BANK_ACCOUNT]')
  .replace(/\b(?:\d[ -]?){12,18}\d\b/g, '[CARD]')
  .replace(/\b\d{11}\b/g, '[NATIONAL_ID]')
  .replace(/(?<![\d./-])(?!\d{1,2}[./-]\d{1,2}[./-]\d{2,4}\b)(?!\d{4}-\d{2}-\d{2}\b)(?:\+|\(\d|\d)[\d\s().-]{7,}\d\b/g, '[PHONE]');

const mask = (text, customerName) => {
  let result = maskPatterns(text);
  const nameParts = String(customerName || '').split(/\s+/).filter((part) => part.length >= 2);

  // 1. The name of the customer, in any common form.
  for (const part of nameParts) {
    // A short stem could match normal words: Theo must not become The.
    const stem = stemOf(part).length >= 4 ? stemOf(part) : part;
    // Short names respect capital letters: Will must not match the word will.
    const flags = stem.length >= 5 ? 'giu' : 'gu';
    result = result.replace(nameRegex(stem, flags), '[CUSTOMER]');
  }

  // 2. Words that usually come right before a person's name.
  const titles = ['colleague','coworker','manager','boss','assistant','wife','husband','Mr','Mrs','Ms','Dr','kolega','kolegi','kolegą','koleżanka','koleżanki','koleżanką','szef','szefowa','szefa','pan','pana','panem','pani','panią','compañero','compañera','jefe','jefa','señor','señora','sr','sra'];
  const titlePattern = titles.map((word) => `[${word[0].toUpperCase()}${word[0].toLowerCase()}]${word.slice(1)}`).join('|');
  result = result.replace(
    new RegExp(`(?<![\\p{L}])((?:${titlePattern})\\.?\\s+)\\p{Lu}\\p{Ll}+(?:\\s+\\p{Lu}\\p{Ll}+)?`, 'gu'),
    '$1[PERSON]'
  );

  // 3. A list of common first names, optionally with a surname after them.
  for (const name of firstNames) {
    const regex = new RegExp(
      `(?<![${L}])${escapeRegex(stemOf(name))}(?:${endings}|k${endings})(?![${L}])(?:\\s+\\p{Lu}\\p{L}+)?`,
      'gu'
    );
    result = result.replace(regex, '[PERSON]');
  }

  // 4. Two capitalised words in a row look like a full name.
  const keep = /^(Customer Support|Forgot Password|Billing Admin|Billing Admins|Best Regards|Kind Regards)$/i;
  const notNames = /^(The|A|An|Our|My|Your|This|That|These|Those|Please|Thanks|Moja|Mój|Nasz|Nasza|Mi|Mis|Nuestro|Nuestra|El|La|Los|Las|Mój)$/;
  const greetings = /^(Hi|Hello|Hey|Dear|Hola|Cześć|Witam|Szanowny|Szanowna)$/;
  result = result.replace(/(?<![\p{L}\[])(\p{Lu}\p{Ll}+)\s+(\p{Lu}\p{Ll}+)(?![\p{L}\]])/gu, (match, first) => {
    if (keep.test(match) || notNames.test(first)) return match;
    if (greetings.test(first)) return `${first} [PERSON]`;
    return '[PERSON]';
  });

  return result;
};

return $input.all().map((item) => ({
  json: {
    ticket_id: item.json.ticket_id,
    subject: mask(item.json.subject, item.json.customer_name),
    message: mask(item.json.message, item.json.customer_name),
  },
}));

const tickets = $('Triage OK?').all();
const masked = $('Mask personal data').all();
const bible = $input.all().map((item) => item.json);

const formatEntry = (entry) => [
  `[${entry.entry_id}] status: ${entry.status}`,
  `Title: ${entry.title}`,
  entry.panel_path ? `Panel path: ${entry.panel_path}` : '',
  `Content: ${entry.content}`,
].filter(Boolean).join('\n');

const confirmedArticles = bible.filter((entry) => entry.entry_type === 'article' && entry.status === 'confirmed');
const bibleText = bible.map(formatEntry).join('\n\n');
const confirmedIds = confirmedArticles.map((entry) => entry.entry_id);
// Longest paths first, so that Home does not break Home > Dashboard.
const confirmedPaths = confirmedArticles
  .map((entry) => entry.panel_path)
  .filter(Boolean)
  .sort((a, b) => b.length - a.length);

return tickets.map((item) => {
  const ticket = item.json;
  const maskedTicket = masked.find((m) => m.json.ticket_id === ticket.ticket_id).json;

  return {
    json: {
      ...ticket,
      masked_subject: maskedTicket.subject,
      masked_message: maskedTicket.message,
      bible_text: bibleText,
      confirmed_ids: confirmedIds,
      confirmed_paths: confirmedPaths,
    },
  };
});

const sources = $('Find bible entries').all();
const priorities = { high: 1, medium: 2, low: 3 };
const promise = /(?<![\p{L}])(as soon as|right away|immediately|shortly|guarantee[sd]?|we will (?:refund|fix|resolve|credit)|you will (?:get|receive) a (?:full )?refund|lo antes posible|de inmediato|garantizamos|reembolsaremos|jak najszybciej|natychmiast|gwarantujemy|zwrócimy)(?![\p{L}])/iu;
const doneAction = /(?:we have|we've|has been|have been)\s+(?:passed|forwarded|sent|escalated|refunded|fixed)\b|\bare passing\b/i;
const internal = /(?<![\p{L}])(urgency|category|priority)(?![\p{L}])|\b[RBTAFG]-\d{3}\b/iu;
const countWords = (text) => text.trim().split(/\s+/).filter(Boolean).length;

return $input.all().map((item, i) => {
  const ticket = sources[i].json;
  const text = (item.json.content || [])
    .filter((block) => block.type === 'text')
    .map((block) => block.text)
    .join('\n')
    .replace(/```json|```/g, '')
    .trim();

  let result = {};
  const problems = [];
  const checks = [];

  if (item.json.error) {
    problems.push('AI call failed after retries');
  } else {
    try {
      result = JSON.parse(text);
    } catch (error) {
      problems.push('AI draft is not valid JSON');
    }
  }

  const draft = typeof result.draft_reply === 'string' ? result.draft_reply.trim() : '';
  const usedEntries = Array.isArray(result.used_entries) ? result.used_entries : [];
  const articles = usedEntries.filter((id) => !String(id).startsWith('R-'));
  const notConfirmed = articles.filter((id) => !ticket.confirmed_ids.includes(id));

  if (!draft) problems.push('Draft is missing');
  if (notConfirmed.length) problems.push(`Entry not confirmed: ${notConfirmed.join(', ')}`);
  if (!articles.length) problems.push('No confirmed bible article was used');

  if (draft) {
    let rest = draft;
    for (const path of ticket.confirmed_paths) rest = rest.split(path).join('');
    if (rest.includes(' > ')) checks.push('Panel path is not in the bible');
    if (countWords(draft) > 80) checks.push(`Draft too long: ${countWords(draft)} words`);
    if (promise.test(draft)) checks.push('Possible promise or timeline');
    if (doneAction.test(draft)) checks.push('Claims an action has already happened');
    if (internal.test(draft)) checks.push('Internal label in draft');
    if (!draft.endsWith('Customer Support')) checks.push('Sign-off is missing');

    const allowed = `${ticket.masked_subject} ${ticket.masked_message}`;
    const unknown = [...draft.matchAll(/\[[A-Z_]+\]/g)].map((m) => m[0]).filter((tag) => !allowed.includes(tag));
    if (unknown.length) checks.push(`Unknown placeholder: ${unknown.join(', ')}`);

    const nameParts = String(ticket.customer_name || '').split(/\s+/).filter((part) => part.length >= 3);
    if (nameParts.some((part) => new RegExp(`(?<![\\p{L}])${part}(?![\\p{L}])`, 'u').test(draft))) {
      checks.push('Customer name in draft');
    }
  }

  const aiGap = typeof result.bible_gap === 'string' ? result.bible_gap.trim() : '';

  return {
    json: {
      ticket_id: ticket.ticket_id,
      subject: ticket.subject,
      message: ticket.message,
      category: ticket.category,
      urgency: ticket.urgency,
      priority: priorities[ticket.urgency] ?? 0,
      reason: ticket.reason,
      draft_reply: draft,
      bible_sources: usedEntries.join(', '),
      needs_human: result.needs_human !== false || problems.length > 0 || checks.length > 0,
      bible_gap: [aiGap, ...problems].filter(Boolean).join(' | '),
      auto_checks: checks.join(' | '),
    },
  };
});

return $input.all().map((item) => ({
  json: {
    ticket_id: item.json.ticket_id,
    subject: item.json.subject,
    message: item.json.message,
    category: item.json.category,
    urgency: item.json.urgency,
    priority: 0,
    reason: item.json.reason,
    draft_reply: '',
    bible_sources: '',
    needs_human: true,
    bible_gap: 'AI triage failed, so no draft was written.',
    auto_checks: '',
  },
}));

const tickets = $('Get demo tickets').all();
const locked = new Set(
  $input.all()
    .map((item) => item.json)
    .filter((row) => row.ticket_id && row.review_status !== 'Pending review')
    .map((row) => row.ticket_id)
);

return tickets
  .filter((item) => !locked.has(item.json.ticket_id))
  .map((item) => ({ json: item.json }));
